import type {
  AttributeInputType,
  AttributeLevel,
  I18nText,
  ShippingMethodKind,
} from "@fluxkit/core";

// Pure data shapes. Entities reference each other by stable code or slug, never by id: ids are generated by the
// database, so the same seed produces different ids on every database.

export interface SeedValue {
  code: string;
  label: I18nText;
}

export interface SeedAttribute {
  code: string;
  name: I18nText;
  inputType: AttributeInputType;
  /** Text attributes are localized unless this says otherwise. */
  isLocalized?: boolean;
  unit?: string;
  validation?: Readonly<Record<string, unknown>>;
  isFilterable?: boolean;
  isSortable?: boolean;
  isInternal?: boolean;
  /** Only for `select` and `multiselect`. */
  options?: readonly SeedValue[];
}

export interface SeedOption {
  code: string;
  name: I18nText;
  values: readonly SeedValue[];
}

export interface SeedProductTypeAttribute {
  attributeCode: string;
  level: AttributeLevel;
  isRequired?: boolean;
}

export interface SeedProductType {
  code: string;
  name: I18nText;
  requiresShipping: boolean;
  attributes: readonly SeedProductTypeAttribute[];
  /** Option codes, in display order. Empty for a type whose products have a single default variant. */
  optionCodes: readonly string[];
}

export interface SeedBrand {
  slug: string;
  name: I18nText;
}

export interface SeedCategory {
  slug: string;
  name: I18nText;
  /** One level of children: the demo tree is two levels deep. */
  children?: readonly SeedCategory[];
}

export interface SeedProductOption {
  optionCode: string;
  valueCodes: readonly string[];
}

export interface SeedMedia {
  /**
   * A file name in `seeds/assets/` (`<name>.webp`, drawn by `scripts/generate-demo-images.mjs`). The runner uploads it
   * through the media service (re-encoded, random key) and saves the URL the upload answered; the data names no URL.
   */
  file: string;
  alt: I18nText;
  /** Ties the image to one option value (for example one color); omit for a gallery image. */
  optionValue?: { optionCode: string; valueCode: string };
}

/**
 * Price and stock of one variant. A variant is identified by its option values (keyed by option code), because SKUs and
 * ids are generated; the default variant of a product without options has an empty `optionValues`.
 */
export interface SeedVariantCommerce {
  optionValues: Readonly<Record<string, string>>;
  /** Minor units (for example kopiykas). The runner stores it in `SHOP_CURRENCY`; the data names no currency. */
  amount: number;
  /** Old price in minor units, strictly greater than `amount`. */
  compareAtAmount?: number;
  /**
   * Units on hand in the default location. Omitted for an untracked variant. `0` means tracked with no stock: the
   * runner writes no inventory level (and no movement) for it.
   */
  stock?: number;
  /** The variant sells beyond its stock; the runner sets the flag through the variant admin service. */
  allowBackorder?: boolean;
}

export interface SeedProduct {
  slug: string;
  title: I18nText;
  description: I18nText;
  productTypeCode: string;
  brandSlug: string;
  /** The first category is the primary one. */
  categorySlugs: readonly string[];
  /** Product-level attribute values keyed by attribute code, in the storage format of ADR 0006 section 4. */
  attributes: Readonly<Record<string, unknown>>;
  options: readonly SeedProductOption[];
  media: readonly SeedMedia[];
  /** Exactly one entry per variant that the options generate. */
  variants: readonly SeedVariantCommerce[];
}

/** A demo delivery method, created INACTIVE through the admin service (the shop activates what it wants to show). */
export interface SeedShippingMethod {
  code: string;
  title: I18nText;
  description: I18nText;
  kind: ShippingMethodKind;
  /** `null` for a method without a carrier; a provider code is created only when that provider is loaded. */
  providerCode: string | null;
  /** In minor units of `SHOP_CURRENCY`, like the product prices (core `validateShippingPricing`). */
  pricing: Readonly<Record<string, unknown>>;
  countryCodes: readonly string[];
  position: number;
}

/** A demo synonym group of catalog search, created only when search is enabled (`SEARCH_ENABLED=true`). */
export interface SeedSynonymGroup {
  /** A locale of `LOCALES`; a group of a locale the shop does not serve is skipped and reported. */
  locale: string;
  /** 2 to 20 terms in the stored form of core `parseSynonymTerms`, none repeated in another group of the locale. */
  terms: readonly string[];
}

export interface CatalogSeed {
  attributes: readonly SeedAttribute[];
  options: readonly SeedOption[];
  productTypes: readonly SeedProductType[];
  brands: readonly SeedBrand[];
  categories: readonly SeedCategory[];
  products: readonly SeedProduct[];
  shippingMethods: readonly SeedShippingMethod[];
  synonymGroups: readonly SeedSynonymGroup[];
}
